<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8" />
  <title>Figure</title>

  <!-- Blocking CDN scripts — no async/defer; must be ready before body <script> runs -->
  <script src="https://cdn.jsdelivr.net/npm/@svgdotjs/svg.js@3/dist/svg.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4/dist/chart.umd.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/expr-eval@2/dist/bundle.min.js"></script>

  <style>
    /* ── Reset ───────────────────────────────────────────────────────────── */
    html,
    body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #fff;
    }

    /* ── Layout ──────────────────────────────────────────────────────────────
       body is a grid so #ui always takes a right-side column instead of covering
       the figure. The #container ResizeObserver then fires 'fig-resize', so
       setPlotFrame re-lays the figure out at its new size automatically.        */
    body {
      display: grid;
      grid-template-columns: 1fr;
      grid-template-rows: 1fr;
      grid-template-areas: "stage";
    }

    /* ── Figure mount point ──────────────────────────────────────────────── */
    #container {
      position: relative;
      grid-area: stage;
      min-width: 0;
      min-height: 0;
      overflow: hidden;
      box-sizing: border-box;
      padding: var(--figure-canvas-padding, 18px);
    }

    /* ── Control panel (mirrors base_scene_new.html #ui) ─────────────────── */
    #ui {
      position: absolute;
      left: 6px;
      bottom: 6px;
      display: flex;
      flex-direction: column;
      gap: 3px;
      font-family: sans-serif;
      font-size: 11px;
      max-width: 190px;
      max-height: 34%;
      overflow-y: auto;
      overflow-x: hidden;
      background: transparent;
      border: 0;
      box-shadow: none;
      opacity: 0.88;
      transform: none;
      transition: opacity 0.16s ease;
      z-index: 10;
    }

    #ui:hover,
    #ui:focus-within {
      opacity: 1;
    }

    #ui button {
      padding: 4px 10px;
      cursor: pointer;
      border: 1px solid #aaa;
      background: #f5f5f5;
      border-radius: 4px;
    }

    #ui button:hover {
      background: #e0e0e0;
    }

    #ui button.active {
      background: #c8e6ff;
      border-color: #5aabf0;
    }

    #ui label {
      display: flex;
      flex-direction: column;
      gap: 2px;
      text-shadow: 0 1px 2px #fff;
    }

    #ui input[type=range] {
      width: 86px;
    }

    /* ── Docked control panel ────────────────────────────────────────────────
       #ui is a grid cell with its own scroll, an opaque background, and roomier
       type. Generated code cannot switch it to an overlay or bottom strip.      */
    body[data-ui-layout="right"] {
      grid-template-columns: 1fr var(--ui-size, 320px);
      grid-template-rows: 1fr;
      grid-template-areas: "stage ui";
    }

    body[data-ui-layout="bottom"] {
      grid-template-columns: 1fr;
      grid-template-rows: 1fr var(--ui-size, 240px);
      grid-template-areas: "stage" "ui";
    }

    body[data-ui-layout="right"] #ui,
    body[data-ui-layout="bottom"] #ui {
      position: relative;
      grid-area: ui;
      left: auto;
      bottom: auto;
      max-width: none;
      max-height: none;
      min-width: 0;
      min-height: 0;
      width: auto;
      height: auto;
      gap: 6px;
      padding: 10px 12px;
      font-size: 12px;
      background: #fbfbfc;
      opacity: 1;
      overflow: auto;
      z-index: 1;
    }

    body[data-ui-layout="right"] #ui {
      border-left: 1px solid #dcdfe3;
    }

    body[data-ui-layout="bottom"] #ui {
      border-top: 1px solid #dcdfe3;
    }

    body[data-ui-layout="right"] #ui label,
    body[data-ui-layout="bottom"] #ui label {
      text-shadow: none;
    }

    body[data-ui-layout="right"] #ui input[type=range],
    body[data-ui-layout="bottom"] #ui input[type=range] {
      width: 100%;
    }

    body[data-ui-layout="right"] #ui textarea,
    body[data-ui-layout="bottom"] #ui textarea {
      width: 100%;
      box-sizing: border-box;
      min-height: 180px;
      resize: vertical;
      font-family: ui-monospace, Consolas, monospace;
      font-size: 11px;
      line-height: 1.45;
      tab-size: 2;
      border: 1px solid #cfd4da;
      border-radius: 4px;
      padding: 6px 8px;
    }

    body[data-ui-layout="bottom"] #ui textarea {
      min-height: 110px;
    }

    /* ── Inline equation parse errors ────────────────────────────────────── */
    .eq-err {
      color: #c00000;
      font-size: 10px;
      max-width: 180px;
      white-space: normal;
      text-shadow: 0 1px 2px #fff;
    }

    /* ── Hover tooltip ───────────────────────────────────────────────────── */
    #figTooltip {
      position: fixed;
      left: 0;
      top: 0;
      display: none;
      max-width: 210px;
      padding: 4px 8px;
      border-radius: 4px;
      background: rgba(0, 0, 0, 0.58);
      color: #fff;
      font: 11px/1.35 sans-serif;
      pointer-events: none;
      white-space: normal;
      z-index: 20;
    }
  </style>
</head>

<body data-ui-layout="right">
  <div id="container"></div>
  <div id="figTooltip"></div>
  <div id="ui">
    <!-- @FIGURE_UI_BEGIN -->
    <!-- @FIGURE_UI_END -->
  </div>

  <!-- Error overlay: shown if CDN fails or JS throws before rendering -->
  <div id="err-overlay" style="display:none;position:fixed;inset:0;background:#fff;z-index:999;
       flex-direction:column;align-items:center;justify-content:center;
       font-family:sans-serif;font-size:13px;color:#555;gap:10px;">
    <span id="err-msg">⚠ Figure failed to load</span>
    <button onclick="location.reload()" style="padding:5px 14px;border:1px solid #aaa;
        border-radius:5px;background:#f5f5f5;cursor:pointer;font-size:12px;">↻ Reload</button>
  </div>

  <script>
    /* ── Error overlay ───────────────────────────────────────────────────── */
    var _rendered = false;
    var _errOverlay = document.getElementById('err-overlay');
    window.__markRendered = function () { _rendered = true; _errOverlay.style.display = 'none'; };
    window.addEventListener('error', function (e) {
      if (!_rendered) {
        document.getElementById('err-msg').textContent = '⚠ ' + (e.message || 'Figure failed to load');
        _errOverlay.style.display = 'flex';
      }
    });
    setTimeout(function () { if (!_rendered) { _errOverlay.style.display = 'flex'; } }, 12000);

    /* ── Tooltip + popup helpers ─────────────────────────────────────────── */
    var _tooltip = document.getElementById('figTooltip');

    function showPopup(title, body) {
      window.parent.postMessage({ type: 'alex-popup', title: title, body: body }, '*');
    }
    function hidePopup() {
      window.parent.postMessage({ type: 'alex-popup', title: null }, '*');
    }
    function showTooltip(text, event) {
      if (!_tooltip || !text) return;
      _tooltip.textContent = text;
      _tooltip.style.display = 'block';
      _moveTooltip(event);
    }
    function _moveTooltip(event) {
      if (!_tooltip || _tooltip.style.display === 'none') return;
      var pad = 12;
      var x = Math.min(event.clientX + pad, window.innerWidth - (_tooltip.offsetWidth || 100) - pad);
      var y = Math.max(pad, event.clientY - (_tooltip.offsetHeight || 40) - pad);
      _tooltip.style.left = x + 'px';
      _tooltip.style.top = y + 'px';
    }
    function hideTooltip() {
      if (_tooltip) _tooltip.style.display = 'none';
    }
    document.addEventListener('mousemove', function (e) { _moveTooltip(e); });

    /* ── Resize event ────────────────────────────────────────────────────── */
    function _containerInnerSize() {
      var container = document.getElementById('container');
      var style = getComputedStyle(container);
      var padX = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
      var padY = (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
      return {
        width: Math.max(0, container.clientWidth - padX),
        height: Math.max(0, container.clientHeight - padY)
      };
    }

    new ResizeObserver(function () {
      var rect = _containerInnerSize();
      document.dispatchEvent(new CustomEvent('fig-resize', {
        detail: { width: rect.width, height: rect.height }
      }));
    }).observe(document.getElementById('container'));

    /* ── UI layout: keep controls in a right-side column ─────────────────────
     * setUiLayout(...) is retained only so older generated payloads do not
     * crash. It deliberately cannot change the side, overlay state, or size.
     * Docking resizes #container, which fires 'fig-resize', so setPlotFrame
     * re-lays the figure out at its new size instead of it being covered.
     */
    var _uiEl = document.getElementById('ui');

    function setUiLayout(mode, sizePx) {
      _autoUiLayout();
    }

    function _applyUiLayout(mode, sizePx) {
      var next = 'right';
      document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', sizePx + 'px');
    }

    // Generated figures do not get to decide panel placement: a stable right
    // column prevents controls from covering the figure and avoids layout jumps.
    var _autoUiTimer = 0;
    function _autoUiLayout() {
      var hasEditor = Boolean(_uiEl.querySelector('textarea'));
      var mode = 'right';
      var start = hasEditor ? 400 : 300;
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      var cap = Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      var size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', size + 'px');
      var guard = 0;
      function step() {
        if (guard++ > 6) return;
        if (_uiEl.scrollHeight <= _uiEl.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', size + 'px');
        requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    window.__autoUiLayout = _autoUiLayout;

    // Re-evaluate when generated code adds controls after first paint.
    new MutationObserver(function () {
      clearTimeout(_autoUiTimer);
      _autoUiTimer = setTimeout(_autoUiLayout, 0);
    }).observe(_uiEl, { childList: true, subtree: true });
    window.addEventListener('resize', function () { _autoUiLayout(); });

    /* ── Keyboard dismiss ────────────────────────────────────────────────── */
    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { hidePopup(); hideTooltip(); }
    });

    /* ── Expression parsing ──────────────────────────────────────────────── */
    /**
     * compileExpr(src, vars) → function(...args)
     *   src  : math source, e.g. 'sin(x) + 1', 'x^2', '2*x - 3'
     *   vars : variable names in argument order, e.g. ['x'] or ['x', 'y']
     * Throws an Error with a readable message on a syntax error or when the
     * source references a variable outside `vars`. Never returns a fallback.
     *
     * DUPLICATED (deliberately): base_scene_new.html has an equivalent ES-module
     * copy. Each scaffold is a standalone served HTML file and neither can
     * import the other, so behaviour changes must be made TWICE.
     * Keep this in sync with compileExpr in base_scene_new.html.
     */
    function compileExpr(src, vars) {
      if (!window.exprEval || !window.exprEval.Parser) {
        throw new Error('Expression parser unavailable (expr-eval CDN did not load)');
      }
      var names = (vars && vars.length) ? vars : ['x'];
      var parsed;
      try {
        parsed = new window.exprEval.Parser().parse(String(src));
      } catch (e) {
        throw new Error('Cannot parse "' + src + '": ' + ((e && e.message) ? e.message : e));
      }
      var used = parsed.variables();
      for (var i = 0; i < used.length; i++) {
        if (names.indexOf(used[i]) === -1) {
          throw new Error('Unknown variable "' + used[i] + '" (expected: ' + names.join(', ') + ')');
        }
      }
      return function () {
        var scope = {};
        for (var j = 0; j < names.length; j++) scope[names[j]] = arguments[j];
        var v;
        try { v = parsed.evaluate(scope); } catch (e) { return NaN; }
        return (typeof v === 'number') ? v : NaN;
      };
    }

    /* ── Plot frame: world → screen mapping (owns resize) ────────────────── */
    var _plotFrame = null;
    var _plots = [];
    var _plotResizeBound = false;

    /**
     * setPlotFrame({ xDomain, yDomain, margin, draw }) → frame
     * Establishes the world→screen mapping used by plotX / plotY and by every
     * plot helper. Call this once, before creating any plots. Registered plots
     * are re-sampled automatically on resize.
     */
    function setPlotFrame(opts) {
      opts = opts || {};
      var innerSize = _containerInnerSize();
      _plotFrame = {
        xDomain: opts.xDomain || [-5, 5],
        yDomain: opts.yDomain || [-5, 5],
        margin: (opts.margin == null) ? 24 : opts.margin,
        draw: opts.draw || SVG().addTo('#container').size('100%', '100%'),
        width: innerSize.width || 900,
        height: innerSize.height || 600
      };
      _recomputePlotScale();
      if (!_plotResizeBound) {
        _plotResizeBound = true;
        document.addEventListener('fig-resize', function (e) {
          if (!_plotFrame) return;
          _plotFrame.width = e.detail.width || _plotFrame.width;
          _plotFrame.height = e.detail.height || _plotFrame.height;
          _recomputePlotScale();
          for (var i = 0; i < _plots.length; i++) _plots[i].sample();
        });
      }
      return _plotFrame;
    }

    function _recomputePlotScale() {
      var f = _plotFrame, m = f.margin;
      f.sx = (f.width - 2 * m) / (f.xDomain[1] - f.xDomain[0]);
      f.sy = (f.height - 2 * m) / (f.yDomain[1] - f.yDomain[0]);
    }

    /** plotX(worldX) → screen px. Requires setPlotFrame() first. */
    function plotX(wx) {
      var f = _plotFrame;
      return f.margin + (wx - f.xDomain[0]) * f.sx;
    }

    /** plotY(worldY) → screen px (y axis flipped). Requires setPlotFrame() first. */
    function plotY(wy) {
      var f = _plotFrame;
      return f.height - f.margin - (wy - f.yDomain[0]) * f.sy;
    }

    function _registerPlot(handle) {
      _plots.push(handle);
      return handle;
    }

    function _unregisterPlot(handle) {
      var i = _plots.indexOf(handle);
      if (i >= 0) _plots.splice(i, 1);
    }

    function _resolveFn(value, vars) {
      if (typeof value === 'function') return value;
      return compileExpr(value, vars);
    }

    function _pointsAttr(points) {
      return points.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
    }

    /**
     * plotFunction(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain, samples=200,
     *           stroke='#1f77b4', width=2, dashed=false }
     * The drawn polyline is ALWAYS produced by sampling the compiled function
     * across `domain`. Non-finite samples split the line into segments instead
     * of drawing a spike.
     */
    function plotFunction(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'plot-' + id);
      var handle = {
        id: id,
        node: group,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setExpr: function (src) { this.fn = _resolveFn(src, vars); return this.sample(); },
        setFn: function (f) { this.fn = f; return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          if (!this.fn) return this;
          var segs = _sampleSegments(this.fn, this.domain, this.samples);
          for (var s = 0; s < segs.length; s++) {
            if (segs[s].length < 2) continue;
            var line = group.polyline(_pointsAttr(segs[s]))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4',
                width: opts.width || 2,
                linecap: 'round',
                linejoin: 'round'
              });
            if (opts.dashed) line.attr('stroke-dasharray', '5,4');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** Sample fn across domain, splitting at non-finite values. → [[ [px,py], … ], …] */
    function _sampleSegments(fn, domain, samples) {
      var a = domain[0], b = domain[1], n = Math.max(2, samples | 0);
      var segs = [], cur = [];
      for (var i = 0; i < n; i++) {
        var t = a + (b - a) * (i / (n - 1));
        var v;
        try { v = fn(t); } catch (e) { v = NaN; }
        if (typeof v === 'number' && isFinite(v)) {
          cur.push([plotX(t), plotY(v)]);
        } else if (cur.length) {
          segs.push(cur);
          cur = [];
        }
      }
      if (cur.length) segs.push(cur);
      return segs;
    }

    /**
     * fillBetween(id, opts) → handle
     *   opts: { lower, upper, variables=['x'], domain, samples=200,
     *           fill='#7fb3ff', opacity=0.45, stroke, strokeWidth=1 }
     * `lower` / `upper` may be expression strings or functions. The polygon is
     * built from EVERY sampled point on both boundaries, so a curved boundary
     * produces a curved region with no caller involvement.
     */
    function fillBetween(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'fill-' + id);
      var handle = {
        id: id,
        node: group,
        lower: opts.lower != null ? _resolveFn(opts.lower, vars) : function () { return 0; },
        upper: opts.upper != null ? _resolveFn(opts.upper, vars) : function () { return 0; },
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setLower: function (src) { this.lower = _resolveFn(src, vars); return this.sample(); },
        setUpper: function (src) { this.upper = _resolveFn(src, vars); return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.domain[0], b = this.domain[1], n = Math.max(2, this.samples | 0);
          var top = [], bottom = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var lo, hi;
            try { lo = this.lower(t); hi = this.upper(t); } catch (e) { lo = NaN; hi = NaN; }
            if (isFinite(lo) && isFinite(hi)) {
              top.push([plotX(t), plotY(hi)]);
              bottom.push([plotX(t), plotY(lo)]);
            }
          }
          if (top.length < 2) return this;
          bottom.reverse();
          var poly = group.polygon(_pointsAttr(top.concat(bottom)))
            .fill({
              color: opts.fill || '#7fb3ff',
              opacity: (opts.opacity == null) ? 0.45 : opts.opacity
            });
          if (opts.stroke) {
            poly.stroke({ color: opts.stroke, width: opts.strokeWidth || 1, linejoin: 'round' });
          } else {
            poly.stroke('none');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /**
     * plotParametric(id, opts) → handle
     *   opts: { x, y, variables=['t'], tDomain=[0,1], samples=200, stroke, width }
     */
    function plotParametric(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['t'];
      var group = _plotFrame.draw.group().attr('id', 'param-' + id);
      var handle = {
        id: id,
        node: group,
        fx: _resolveFn(opts.x, vars),
        fy: _resolveFn(opts.y, vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX: function (src) { this.fx = _resolveFn(src, vars); return this.sample(); },
        setY: function (src) { this.fy = _resolveFn(src, vars); return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.tDomain[0], b = this.tDomain[1], n = Math.max(2, this.samples | 0);
          var pts = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var vx, vy;
            try { vx = this.fx(t); vy = this.fy(t); } catch (e) { vx = NaN; vy = NaN; }
            if (isFinite(vx) && isFinite(vy)) pts.push([plotX(vx), plotY(vy)]);
          }
          if (pts.length >= 2) {
            group.polyline(_pointsAttr(pts))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4', width: opts.width || 2,
                linecap: 'round', linejoin: 'round'
              });
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** integrateSimpson(fn, a, b, n=200) → number. Composite Simpson's rule. */
    function integrateSimpson(fn, a, b, n) {
      n = Math.max(2, n || 200);
      if (n % 2) n++;
      var h = (b - a) / n, s = fn(a) + fn(b);
      for (var i = 1; i < n; i++) s += fn(a + i * h) * ((i % 2) ? 4 : 2);
      return (s * h) / 3;
    }

    /** findRoot(fn, a, b, tol=1e-9) → number | null. Bisection; null if no sign change. */
    function findRoot(fn, a, b, tol) {
      tol = tol || 1e-9;
      var fa = fn(a), fb = fn(b);
      if (!isFinite(fa) || !isFinite(fb) || fa * fb > 0) return null;
      for (var i = 0; i < 200; i++) {
        var m = (a + b) / 2, fm = fn(m);
        if (!isFinite(fm)) return null;
        if (Math.abs(fm) < tol || (b - a) / 2 < tol) return m;
        if (fa * fm < 0) { b = m; } else { a = m; fa = fm; }
      }
      return (a + b) / 2;
    }

    /* ── Equation input binding ──────────────────────────────────────────── */
    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs under one parent, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_new.html.
     */
    function _equationErrorSlot(input) {
      var parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        var slotId = 'eq-err-' + input.id;
        var byId = document.getElementById(slotId);
        if (byId) return byId;
        var namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      var existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      var span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → function(fn, src)
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify2dHtml catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_new.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') {
        return function (fn, src) { t(fn, src); };
      }
      if (t && t.handle) {
        var method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            'bindEquationInput("' + inputId + '"): target handle has no method "' + method +
            '". Use { handle, method: \'...\' } with a method the handle really has ' +
            '(plotFunction: setExpr, setFn; fillBetween: setLower, setUpper; ' +
            'plotParametric: setX, setY).'
          );
        }
        return function (fn) { t.handle[method](fn); };
      }
      if (t && typeof t.setFn === 'function') {
        return function (fn) { t.setFn(fn); };
      }
      throw new Error(
        'bindEquationInput("' + inputId + '"): this target cannot be driven — it is not a ' +
        'function and has no .setFn. Handles without .setFn (fillBetween, plotParametric) ' +
        'must be passed as { handle, method: \'setUpper\' } naming the setter to call.'
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     *   targets: a plot handle, a { handle, method } pair, a function(fn, src),
     *            or an array of any of those.
     *   opts   : { variables=['x'], onChange(fn, src) }
     *
     * On every valid edit, every target re-samples. On a parse error the last
     * good curve is kept and the message is shown inline — this function NEVER
     * substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_new.html.
     */
    function bindEquationInput(inputId, targets, opts) {
      opts = opts || {};
      var input = document.getElementById(inputId);
      if (!input) throw new Error('bindEquationInput: no element with id "' + inputId + '"');
      var vars = opts.variables || ['x'];
      var list = Array.isArray(targets) ? targets : [targets];
      var slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      var appliers = [];
      for (var k = 0; k < list.length; k++) appliers.push(_resolveEqTarget(inputId, list[k]));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          var fn = compileExpr(src, vars);
          for (var i = 0; i < appliers.length; i++) appliers[i](fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', function () { apply(input.value); });
      apply(input.value);
      return { apply: apply, input: input, errorSlot: slot };
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();
  </script>
</body>

</html>

GLOBALS (do not re-declare): showPopup(title,body), showTooltip(text,event), hideTooltip(), #container (mount target), window.__markRendered() (call once when drawn), 'fig-resize' CustomEvent on document, setUiLayout(mode, sizePx).
  #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel. Docking resizes #container and fires 'fig-resize', so setPlotFrame re-lays the figure out at its new size.

LIBRARY: SVG.js v3 (global: SVG). var draw=SVG().addTo(document.getElementById('container')).size('100%','100%'); var W=600,H=Math.round(W*(3/4)); draw.viewbox(0,0,W,H). font-size in user units (no px). Hover: el.on('mousemove',e=>showTooltip('label',e)).on('mouseleave',()=>hideTooltip()).on('click',()=>showPopup('Title','body')); el.css('cursor','pointer'). window.__markRendered() synchronously at end.
PLOTTING HELPERS (do not re-declare, and do NOT define your own X()/Y() — use plotX/plotY):
  setPlotFrame({ xDomain, yDomain, margin }) → call ONCE before creating plots; establishes world→screen and owns resize (do not write your own plot resize handler)
  plotX(worldX) / plotY(worldY) → screen px
  compileExpr(src, vars) → f(...args); throws on a bad expression and never returns a fallback
  bindEquationInput(inputId, targets, { variables, onChange }) → wires an <input> to plot handles and shows parse errors inline
  plotFunction(id, { expr, variables, domain, samples, stroke, width, dashed }) → handle
  fillBetween(id, { lower, upper, variables, domain, samples, fill, opacity }) → handle
  plotParametric(id, { x, y, variables, tDomain, samples, stroke }) → handle
  variables: the argument names the expression may use, in order (defaults: plotFunction ['x'], fillBetween ['x'], plotParametric ['t']). When a blueprint field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotFunction('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  integrateSimpson(fn, a, b, n) → number;  findRoot(fn, a, b, tol) → number | null
  Handles re-sample on EVERY setter call, and the setters differ: plotFunction → .setExpr / .setFn / .setDomain · fillBetween → .setLower / .setUpper / .setDomain · plotParametric → .setX / .setY. All handles also have .sample() and .remove().

VISUAL FIDELITY: the default state must be a faithful inline replacement for the source image.
- Color scheme: match every color exactly — axis lines, data series, fills, backgrounds
- Layout & proportions: same relative element positions, same axis ranges, same tick marks and gridlines
- Data shape: match curve trajectories, bar heights, scatter clusters, or node/edge layout — approximate magnitudes, not invented
- Labels & annotations: every label visible in the original must appear at the same position; use blueprint.reconstructionNotes for text and color coding
- Line styles: dashed vs solid, stroke weights, arrowhead presence — copy from the image
- The step-0 (default) state should look indistinguishable from the original at a glance, with no title bar or toolbar visible

TEXT PLACEMENT & READABILITY: faithful labels must still be readable.
- Treat every label, tick label, annotation, formula, and legend item as a collision-checked box, and check each one against lines, arrows, curves, points, nodes, tick marks, gridlines, controls, and other text before finalizing. Text must not sit on top of strokes or dense marks.
- If the source label is anchored to a busy line/arrow/node, keep the semantic anchor but move the text to the nearest open whitespace and connect it with a short leader line, pointer, or subtle dot.
- Draw text and label backgrounds after geometry so labels are on top. Over busy regions add a small white/translucent background rect, or a halo: text.attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' }).
- Do not add extra visible explanatory text inside the figure; use hover tooltips, click popups, and the scaffold narration panel for explanation.

SCALE SAFETY: figures may be stitched into chapters at different sizes.
- With Canvas, Chart.js custom drawing, or any pixel-based renderer, derive point radius, stroke width, arrowheads, ticks, label size, and annotation padding from min(plotWidth, plotHeight). Avoid large fixed pixel minimums such as Math.max(20, scaledRadius); use only small clamps that prevent invisibility.
- With SVG/viewBox geometry that already scales naturally, preserve that and avoid fixed px sizes that break it.
- If space is small, simplify or hide secondary labels instead of making marks oversized.

HOVER/CLICK (on user action only): hover → showTooltip(label,event)/hideTooltip(); cursor:pointer on interactive elements. Click → showPopup('Title','2–3 sentence explanation'). Animation: fill/opacity transitions only; no scale/translate/bounce.

CONTROLS (blueprint.interactions — render in UI section; add id="{id}Input" to every input). Each control's handler must teach the concept described in its "teaches" field:
  slider → <label>{label}: <output id="{id}Val">{default}</output><input id="{id}Input" type="range" min="{min}" max="{max}" step="{step}" value="{default}" oninput="document.getElementById('{id}Val').value=this.value;update_{id}(+this.value)"></label>  +  function update_{id}(v){}
  toggle → <label><input id="{id}Input" type="checkbox" onchange="toggle_{id}(this.checked)"> {label}</label>  +  function toggle_{id}(on){}
  button → <button onclick="trigger_{id}()">{label}</button>  +  function trigger_{id}(){}
  equation_input → one <label>{field.label} <input id="{field.id}Input" value="{field.default}"></label> per entry in the interaction's "fields"
  code_editor → a <textarea id="{id}Code"> plus sample tabs, an input for the interaction's "input", a Run button, and playback controls

DEMO STEPS (blueprint.demo_steps): if present and non-empty, build a step player in #ui:
  - A <p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"> showing the current step's narration
  - <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
  - Each step's .state sets matching interaction inputs to the specified values and calls their update functions
  - Step 0 is the default view (set on load); subsequent steps are one click away
  - Omit the player entirely if demo_steps is absent or empty

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In Graham's scan, the turn direction at the top of the stack decides hull membership: a left turn at p_j means the new point p_i expands the hull, while a nonleft turn means the middle point p_t lies inside the triangle p_i p_r p_0 and can never be a convex-hull vertex.
KEY INSIGHT (what students should walk away understanding): A nonleft turn is not just a local wiggle — it is a certificate that the middle point sits inside the triangle formed by its neighbor, the candidate, and p_0, so popping it can never remove a true hull vertex.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "In Graham's scan, the turn direction at the top of the stack decides hull membership: a left turn at p_j means the new point p_i expands the hull, while a nonleft turn means the middle point p_t lies inside the triangle p_i p_r p_0 and can never be a convex-hull vertex.",
  "figureType": "diagram",
  "elements": [
    "Panel (a) label centered under the left figure",
    "Panel (b) label centered under the right figure",
    "Panel (a): light-gray filled convex polygon Q_j with italic label 'Q_j' in its interior",
    "Panel (a): boundary vertices of Q_j drawn as small filled black dots — p_0 (bottom left), p_j (top), p_k (upper right of p_j), two unlabeled dots along the upper-right chain, p_2 (right), p_1 (lower right)",
    "Panel (a): thick gray polyline forming the hull boundary of Q_j from p_0 up to p_j, across through p_k and the unlabeled dots, down to p_2, back through p_1 to p_0",
    "Panel (a): darker-gray filled triangle p_0–p_j–p_i attached on the left side of Q_j, with p_i lying outside Q_j",
    "Panel (a): vertex labels p_i, p_j, p_k, p_2, p_1, p_0 in italic serif, offset outward from each dot",
    "Panel (a): the shared edge p_0–p_j drawn as the internal boundary between the two shaded regions",
    "Panel (b): thick gray open hull chain from p_0 along the bottom to p_1, up the right side through two unlabeled dots, across the top through an unlabeled dot to p_j, and continuing left toward p_i",
    "Panel (b): small filled black dots at p_0, p_1, p_j, p_i, p_r, p_t and the unlabeled intermediate hull points",
    "Panel (b): thin-outlined light-gray triangle with corners p_i (upper left), p_r (upper right of p_i), p_0 (bottom)",
    "Panel (b): interior point p_t inside the triangle",
    "Panel (b): dashed segments p_t–p_i and p_t–p_r",
    "Panel (b): small arc at p_t marking the angle ∠p_i p_t p_r (obtuse, reflex-side indicator of the nonleft turn)",
    "Panel (b): vertex labels p_i, p_r, p_t, p_j, p_1, p_0",
    "Stack readout strip showing the current Graham-scan stack contents (bottom-to-top) for the stepping interaction",
    "Turn-test annotation box showing the current triple (prev, top, candidate) and the verdict 'left turn → push' or 'nonleft turn → pop'",
    "Legend: light gray = current hull region, dark gray = region added by the new point, dashed = evidence that a point is interior"
  ],
  "interactions": [
    {
      "id": "caseToggle",
      "type": "toggle",
      "teaches": "That the same turn test has two outcomes: a left turn grows the hull (panel a), a nonleft turn proves the middle point is trapped inside a triangle of other points (panel b).",
      "label": "Case",
      "options": [
        "(a) left turn — point joins hull",
        "(b) nonleft turn — point is interior",
        "both panels"
      ],
      "default": "both panels"
    },
    {
      "id": "scanStep",
      "type": "state",
      "teaches": "That Graham's scan processes points in sorted angular order, and at each candidate it repeatedly pops while the top of the stack makes a nonleft turn before pushing the candidate.",
      "label": "Graham-scan stack update",
      "states": [
        "start",
        "test p_j (left turn)",
        "push p_i onto stack",
        "test p_t (nonleft turn)",
        "pop p_t",
        "push p_r",
        "done"
      ],
      "default": "start"
    },
    {
      "id": "pointFocus",
      "type": "click",
      "teaches": "Which specific neighboring points act as the witnesses that place the clicked point on the hull boundary or strictly inside it.",
      "teachesDetail": "Clicking p_i, p_j, p_r or p_t highlights that point and its supporting triangle or hull edge."
    }
  ],
  "demo_steps": [
    {
      "title": "The hull so far",
      "narration": "Panel (a) shows Q_j, the convex hull of the points processed so far, with p_0 at the bottom and p_j at the current top of the stack. Every vertex of Q_j is on the stack in counterclockwise order.",
      "state": {
        "caseToggle": "(a) left turn — point joins hull",
        "scanStep": "start"
      }
    },
    {
      "title": "Test the next point: a left turn",
      "narration": "The candidate p_i is tested against the top two stack entries. The turn at p_j is a left turn, so p_j stays and p_i is accepted — the dark triangle p_0 p_j p_i is the new territory the hull gains.",
      "state": {
        "caseToggle": "(a) left turn — point joins hull",
        "scanStep": "test p_j (left turn)"
      }
    },
    {
      "title": "Push p_i",
      "narration": "p_i is pushed onto the stack and the hull boundary now bends outward through p_i. Notice the enlarged polygon is still convex.",
      "state": {
        "caseToggle": "(a) left turn — point joins hull",
        "scanStep": "push p_i onto stack"
      }
    },
    {
      "title": "A nonleft turn instead",
      "narration": "Panel (b) shows the opposite outcome: the turn at p_t from p_i to p_r is not a left turn. The dashed segments and the marked angle at p_t reveal p_t lies inside triangle p_i p_r p_0.",
      "state": {
        "caseToggle": "(b) nonleft turn — point is interior",
        "scanStep": "test p_t (nonleft turn)"
      }
    },
    {
      "title": "Pop the interior point",
      "narration": "Because p_t is a convex combination of p_i, p_r and p_0, it can never be a hull vertex, so it is popped off the stack — this is why the pop is safe and permanent.",
      "state": {
        "caseToggle": "(b) nonleft turn — point is interior",
        "scanStep": "pop p_t"
      }
    },
    {
      "title": "Push the candidate and compare",
      "narration": "With p_t gone, p_r is pushed and the chain is convex again. Viewing both panels together contrasts the point that enlarges the hull with the point that is enclosed and discarded.",
      "state": {
        "caseToggle": "both panels",
        "scanStep": "push p_r"
      }
    }
  ],
  "keyInsight": "A nonleft turn is not just a local wiggle — it is a certificate that the middle point sits inside the triangle formed by its neighbor, the candidate, and p_0, so popping it can never remove a true hull vertex.",
  "reconstructionNotes": "Two side-by-side panels on white, each about half the width, with italic serif point labels and small filled black dots at every vertex. Panel (a): a light-gray (about 15% gray) convex polygon labeled Q_j occupying the right two-thirds, its thick medium-gray outline running p_0 (bottom left) → p_j (top) → p_k → two unlabeled dots → p_2 (right) → p_1 (lower right) → back to p_0; a darker gray (about 35% gray) triangle p_0–p_j–p_i hangs off the left, p_i well outside the original hull, so the union reads as one larger convex polygon. Panel (b): a thick medium-gray open chain traces the right portion of a hull from p_0 (bottom left) rightward to p_1, up the right side through two unlabeled dots, across the top through a dot to p_j, heading left toward p_i; at the left a narrow light-gray triangle with thin black outline has corners p_i (upper left), p_r (upper right, near the chain), p_0 (bottom), with p_t a dot inside it, thin dashed segments from p_t to p_i and to p_r, and a small dashed arc at p_t marking the angle. Labels (a) and (b) centered below each panel. Highlight color for clicks and the active turn test should be a saturated accent (e.g. orange) applied to the focal point, its two witness segments, and the supporting triangle fill; the stack readout and turn verdict appear as a small text strip below the panels.",
  "figureType_note": "diagram → rendered with SVG.js so arbitrary polygons, dashed witnesses, and highlight states can be redrawn per step."
}

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600;font-size:12px">Graham's scan: the turn test</span>
<p id="demoNarration" style="margin:0;font-size:11px;line-height:1.5;min-height:74px"></p>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;min-width:96px;text-align:center"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Case
  <select id="caseToggleInput" onchange="toggle_caseToggle(this.value)">
    <option value="a">(a) left turn — point joins hull</option>
    <option value="b">(b) nonleft turn — point is interior</option>
    <option value="both" selected>both panels</option>
  </select>
</label>
<label>Graham-scan stack update
  <select id="scanStepInput" onchange="update_scanStep(+this.value)">
    <option value="0" selected>start</option>
    <option value="1">test p_j (left turn)</option>
    <option value="2">push p_i onto stack</option>
    <option value="3">test p_t (nonleft turn)</option>
    <option value="4">pop p_t</option>
    <option value="5">push the candidate</option>
    <option value="6">done</option>
  </select>
</label>
<span style="font-size:11px;color:#555;line-height:1.4">Click <i>p<sub>i</sub></i>, <i>p<sub>j</sub></i>, <i>p<sub>r</sub></i> or <i>p<sub>t</sub></i> in the figure to see the witnesses that decide its fate.</span>
<span style="display:flex;gap:6px">
  <button onclick="trigger_clearFocus()">Clear highlight</button>
  <button onclick="trigger_insight()">Key insight</button>
</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var NS = 'http://www.w3.org/2000/svg';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 880, H = 430;
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

var C = {
  light: '#d8d8d8', dark: '#a9a9a9', hull: '#8f8f8f', thin: '#6f6f6f',
  accent: '#e8730c', accentFill: '#f8ddc0', good: '#1a7f37', bad: '#b3361f',
  ink: '#111', soft: '#555'
};

/* ---------- geometry (panel-local coordinates, ~400 x 330) ---------- */
var PA = {
  p0: [95, 247], pj: [128, 42], pk: [232, 43], d1: [303, 63],
  d2: [350, 130], p2: [358, 158], p1: [316, 228], pi: [35, 82]
};
var PB = {
  p0: [95, 252], p1: [300, 228], e1: [352, 162], e2: [356, 104],
  e3: [312, 66], e4: [242, 45], pj: [168, 38], pr: [132, 96],
  pi: [68, 92], pt: [106, 124]
};

var gA = draw.group(), gB = draw.group(), gStrip = draw.group();

/* ---------- state ---------- */
var caseMode = 'both';
var stepIdx = 0;
var focusKey = null;
var demoIdx = 0;

/* ---------- text helpers ---------- */
function rich(parent, x, y, parts, opts) {
  opts = opts || {};
  var size = opts.size || 13;
  var t = parent.text(' ');
  var n = t.node;
  while (n.firstChild) n.removeChild(n.firstChild);
  n.setAttribute('x', x); n.setAttribute('y', y);
  n.removeAttribute('dy');
  n.setAttribute('text-anchor', opts.anchor || 'start');
  n.setAttribute('font-family', opts.family || 'Georgia,"Times New Roman",Times,serif');
  n.setAttribute('font-size', size);
  n.setAttribute('fill', opts.fill || C.ink);
  if (opts.opacity != null) n.setAttribute('opacity', opts.opacity);
  if (opts.halo !== false) {
    n.setAttribute('paint-order', 'stroke');
    n.setAttribute('stroke', '#ffffff');
    n.setAttribute('stroke-width', opts.haloW || 3);
    n.setAttribute('stroke-linejoin', 'round');
  }
  var pending = 0;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    var s = document.createElementNS(NS, 'tspan');
    s.textContent = p.t;
    if (p.it) s.setAttribute('font-style', 'italic');
    if (p.fill) s.setAttribute('fill', p.fill);
    if (p.sub) {
      s.setAttribute('font-size', Math.round(size * 0.72 * 10) / 10);
      s.setAttribute('dy', size * 0.24);
      pending += size * 0.24;
    } else if (pending) { s.setAttribute('dy', -pending); pending = 0; }
    n.appendChild(s);
  }
  return t;
}
function pn(sub, fill) { return [{ t: 'p', it: 1, fill: fill }, { t: sub, it: 1, sub: 1, fill: fill }]; }
function tx(s, fill) { return [{ t: s, fill: fill }]; }
function cat() { var out = []; for (var i = 0; i < arguments.length; i++) out = out.concat(arguments[i]); return out; }

function pts(arr) { return arr.map(function (p) { return p[0] + ',' + p[1]; }).join(' '); }

function arcPts(c, a0, a1, r, steps) {
  var d = a1 - a0;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  var out = [];
  steps = steps || 26;
  for (var i = 0; i <= steps; i++) {
    var a = a0 + d * i / steps;
    out.push([c[0] + r * Math.cos(a), c[1] + r * Math.sin(a)]);
  }
  return out;
}
function ang(from, to) { return Math.atan2(to[1] - from[1], to[0] - from[0]); }

function hit(g, p, tip, key, title, body) {
  var h = g.circle(22).center(p[0], p[1]).fill('#fff').opacity(0).css('cursor', 'pointer');
  h.on('mousemove', function (e) { showTooltip(tip, e); });
  h.on('mouseleave', hideTooltip);
  if (key) h.on('click', function () { focusKey = (focusKey === key ? null : key); render(); if (focusKey) showPopup(title, body); else hidePopup(); });
  return h;
}
function dot(g, p, r, fill) { return g.circle((r || 4) * 2).center(p[0], p[1]).fill(fill || '#000'); }
function ring(g, p) { g.circle(24).center(p[0], p[1]).fill('none').stroke({ color: C.accent, width: 2.5 }); }
function region(el, tip) {
  el.css('cursor', 'help');
  el.on('mousemove', function (e) { showTooltip(tip, e); }).on('mouseleave', hideTooltip);
  return el;
}

/* ---------- panel (a) ---------- */
function drawA(g) {
  var P = PA;
  var merged = stepIdx >= 2;
  var poly = [P.p0, P.pj, P.pk, P.d1, P.d2, P.p2, P.p1];
  var polyM = [P.p0, P.pi, P.pj, P.pk, P.d1, P.d2, P.p2, P.p1];

  if (merged) {
    region(g.polygon(pts(polyM)).fill(C.light).stroke('none'),
      'Enlarged hull after pushing p_i — still convex');
    g.line(P.p0[0], P.p0[1], P.pj[0], P.pj[1]).stroke({ color: '#9b9b9b', width: 1.3, dasharray: '5,4' });
  } else {
    region(g.polygon(pts(poly)).fill(C.light).stroke('none'),
      'Q_j : convex hull of the points processed so far');
    region(g.polygon(pts([P.p0, P.pj, P.pi])).fill(C.dark).stroke('none'),
      'Territory the hull gains when p_i is pushed');
  }

  if (merged) {
    g.polygon(pts(polyM)).fill('none').stroke({ color: C.hull, width: 5, linejoin: 'round' });
  } else {
    g.polygon(pts(poly)).fill('none').stroke({ color: C.hull, width: 5, linejoin: 'round' });
    g.polyline(pts([P.p0, P.pi, P.pj])).fill('none').stroke({ color: C.thin, width: 2, linejoin: 'round' });
  }

  /* step highlights */
  if (stepIdx === 1) {
    g.polyline(pts([P.pk, P.pj, P.pi])).fill('none')
      .stroke({ color: C.accent, width: 4.5, linejoin: 'round', linecap: 'round' });
    g.polyline(pts(arcPts(P.pj, ang(P.pj, P.pk), ang(P.pj, P.pi), 30)))
      .fill('none').stroke({ color: C.accent, width: 1.6, dasharray: '4,3' });
  }
  if (stepIdx === 2) {
    g.polyline(pts([P.p0, P.pi, P.pj])).fill('none')
      .stroke({ color: C.accent, width: 4.5, linejoin: 'round', linecap: 'round' });
  }
  if (focusKey === 'A.pi') { g.polyline(pts([P.p0, P.pi, P.pj])).fill('none').stroke({ color: C.accent, width: 4, linejoin: 'round' }); ring(g, P.pi); }
  if (focusKey === 'A.pj') {
    g.polyline(pts([P.pk, P.pj, P.pi])).fill('none').stroke({ color: C.accent, width: 4, linejoin: 'round' });
    ring(g, P.pj);
  }

  /* dots */
  [P.p0, P.pj, P.pk, P.d1, P.d2, P.p2, P.p1, P.pi].forEach(function (p) { dot(g, p, 4); });
  if (stepIdx === 1 || stepIdx === 2) { dot(g, P.pi, 5, C.accent); dot(g, P.pj, 5, C.accent); }

  /* labels */
  rich(g, 215, 148, [{ t: 'Q', it: 1 }, { t: 'j', it: 1, sub: 1 }], { size: 19, anchor: 'middle' });
  rich(g, 20, 78, pn('i'), { size: 16, anchor: 'end' });
  rich(g, 120, 26, pn('j'), { size: 16, anchor: 'middle' });
  rich(g, 243, 26, pn('k'), { size: 16, anchor: 'middle' });
  rich(g, 372, 168, pn('2'), { size: 16, anchor: 'start' });
  rich(g, 332, 244, pn('1'), { size: 16, anchor: 'start' });
  rich(g, 82, 274, pn('0'), { size: 16, anchor: 'middle' });
  rich(g, 200, 316, tx('(a)'), { size: 15, anchor: 'middle', family: 'Georgia,serif' });

  /* interaction */
  hit(g, P.pi, 'p_i — the new candidate point', 'A.pi', 'p_i joins the hull',
    'The turn p_k → p_j → p_i is a LEFT turn, so nothing is popped and p_i is pushed onto the stack. The dark triangle p_0 p_j p_i is exactly the region the hull gains.');
  hit(g, P.pj, 'p_j — current top of the stack', 'A.pj', 'p_j survives the test',
    'p_j is the top of the stack. Graham\'s scan examines the triple (p_k, p_j, p_i); because it turns left, p_j is still a corner of the enlarged hull and stays on the stack.');
  hit(g, P.p0, 'p_0 — the lowest point, bottom of the stack', null);
}

/* ---------- panel (b) ---------- */
function drawB(g) {
  var P = PB;
  var popped = stepIdx >= 4;
  var pushed = stepIdx >= 5;
  var chain = [P.p0, P.p1, P.e1, P.e2, P.e3, P.e4, P.pj, P.pr];

  /* triangle p_i p_r p_0 */
  var triFill = (stepIdx === 3 || focusKey === 'B.pt') ? C.accentFill : C.light;
  if (!pushed) {
    region(g.polygon(pts([P.pi, P.pr, P.p0])).fill(triFill).stroke({ color: '#222', width: 1 }),
      'Triangle p_i p_r p_0 — every point inside it is interior to the hull');
  } else {
    g.polygon(pts([P.pi, P.pr, P.p0])).fill('none').stroke({ color: '#bdbdbd', width: 1, dasharray: '4,4' });
  }

  /* hull chain */
  g.polyline(pts(chain)).fill('none').stroke({ color: C.hull, width: 5, linejoin: 'round', linecap: 'round' });
  if (pushed) {
    g.polyline(pts([P.pr, P.pi])).fill('none')
      .stroke({ color: stepIdx === 5 ? C.accent : C.hull, width: 5, linejoin: 'round', linecap: 'round' });
  }

  /* dashed witnesses + angle mark */
  if (!pushed) {
    var dCol = (stepIdx === 3 || focusKey === 'B.pt') ? C.accent : '#333';
    var dOp = popped ? 0.35 : 1;
    g.line(P.pt[0], P.pt[1], P.pi[0], P.pi[1]).stroke({ color: dCol, width: 1.2, dasharray: '4,3' }).opacity(dOp);
    g.line(P.pt[0], P.pt[1], P.pr[0], P.pr[1]).stroke({ color: dCol, width: 1.2, dasharray: '4,3' }).opacity(dOp);
    g.polyline(pts(arcPts(P.pt, ang(P.pt, P.pi), ang(P.pt, P.pr), 26)))
      .fill('none').stroke({ color: dCol, width: 1.2, dasharray: '3,2.5' }).opacity(dOp);
  }

  if (stepIdx === 3) {
    g.polyline(pts([P.pr, P.pt, P.pi])).fill('none')
      .stroke({ color: C.accent, width: 3.2, linejoin: 'round', linecap: 'round' }).opacity(0.85);
  }
  if (focusKey === 'B.pr') { g.polyline(pts([P.pi, P.pr, P.p0])).fill('none').stroke({ color: C.accent, width: 3.5, linejoin: 'round' }); ring(g, P.pr); }
  if (focusKey === 'B.pi') { g.polyline(pts([P.pr, P.pi, P.p0])).fill('none').stroke({ color: C.accent, width: 3.5, linejoin: 'round' }); ring(g, P.pi); }
  if (focusKey === 'B.pt' && !pushed) ring(g, P.pt);

  /* dots */
  [P.p0, P.p1, P.e1, P.e2, P.e3, P.e4, P.pj, P.pr, P.pi].forEach(function (p) { dot(g, p, 4); });
  if (stepIdx === 3) { dot(g, P.pt, 5, C.accent); dot(g, P.pr, 5, C.accent); dot(g, P.pi, 5, C.accent); }
  if (!popped) { if (stepIdx !== 3) dot(g, P.pt, 4); }
  else if (!pushed) {
    g.circle(9).center(P.pt[0], P.pt[1]).fill('#fff').stroke({ color: C.bad, width: 1.4 });
    g.line(P.pt[0] - 5, P.pt[1] - 5, P.pt[0] + 5, P.pt[1] + 5).stroke({ color: C.bad, width: 1.6 });
    g.line(P.pt[0] - 5, P.pt[1] + 5, P.pt[0] + 5, P.pt[1] - 5).stroke({ color: C.bad, width: 1.6 });
  }
  if (pushed) dot(g, P.pi, 5, stepIdx === 5 ? C.accent : '#000');

  /* labels */
  rich(g, 52, 90, pn('i'), { size: 16, anchor: 'end' });
  rich(g, 144, 90, pn('r'), { size: 16, anchor: 'start' });
  if (!pushed) rich(g, 104, 148, pn('t'), { size: 16, anchor: 'middle', fill: popped ? C.bad : C.ink, opacity: popped ? 0.6 : 1 });
  rich(g, 162, 22, pn('j'), { size: 16, anchor: 'middle' });
  rich(g, 314, 246, pn('1'), { size: 16, anchor: 'start' });
  rich(g, 86, 278, pn('0'), { size: 16, anchor: 'middle' });
  rich(g, 200, 316, tx('(b)'), { size: 15, anchor: 'middle', family: 'Georgia,serif' });

  /* interaction */
  hit(g, P.pi, 'p_i — the candidate being tested', 'B.pi', 'p_i is the candidate',
    'p_i is the next point in angular order. Together with p_r and p_0 it forms the triangle that traps p_t, which is why p_t can be discarded before p_i is pushed.');
  hit(g, P.pr, 'p_r — next-to-top of the stack', 'B.pr', 'p_r is the witness below p_t',
    'p_r sits immediately below p_t on the stack. It supplies one corner of triangle p_i p_r p_0; after p_t is popped, p_r becomes the new top and the chain p_r → p_i turns left.');
  if (!pushed) hit(g, P.pt, 'p_t — top of stack, makes a nonleft turn', 'B.pt', 'p_t is trapped inside the triangle',
    'The turn (p_r, p_t, p_i) is not a left turn. That certifies p_t lies inside triangle p_i p_r p_0, so p_t is a convex combination of three other points and can never be a hull vertex — popping it is safe and permanent.');
  hit(g, P.p0, 'p_0 — the lowest point, bottom of the stack', null);
}

/* ---------- bottom strip: stack readout, verdict, legend ---------- */
var STACKS = [
  { s: ['0', '1', '2', '…', 'k', 'j'], cand: null },
  { s: ['0', '1', '2', '…', 'k', 'j'], cand: 'i' },
  { s: ['0', '1', '2', '…', 'k', 'j', 'i'], cand: null },
  { s: ['0', '1', '…', 'j', 'r', 't'], cand: 'i' },
  { s: ['0', '1', '…', 'j', 'r'], cand: 'i' },
  { s: ['0', '1', '…', 'j', 'r', 'i'], cand: null },
  { s: ['0', '1', '…', 'j', 'r', 'i'], cand: null }
];

function verdictParts(i) {
  if (i === 1) return { col: C.good, bg: '#e8f6ec', p: cat(tx('turn ('), pn('k'), tx(', '), pn('j'), tx(', '), pn('i'), tx(')  =  LEFT TURN  →  keep '), pn('j'), tx(', push '), pn('i')) };
  if (i === 2) return { col: C.good, bg: '#e8f6ec', p: cat(pn('i'), tx(' pushed — the hull grows by the dark triangle '), pn('0'), tx(' '), pn('j'), tx(' '), pn('i')) };
  if (i === 3) return { col: C.bad, bg: '#fdecea', p: cat(tx('turn ('), pn('r'), tx(', '), pn('t'), tx(', '), pn('i'), tx(')  =  NONLEFT  →  '), pn('t'), tx(' lies inside \u25B3'), pn('i'), tx(' '), pn('r'), tx(' '), pn('0'), tx('  →  pop')) };
  if (i === 4) return { col: C.bad, bg: '#fdecea', p: cat(pn('t'), tx(' popped — an interior point can never be a hull vertex')) };
  if (i === 5) return { col: C.good, bg: '#e8f6ec', p: cat(tx('candidate '), pn('i'), tx(' pushed — the chain '), pn('r'), tx(' \u2192 '), pn('i'), tx(' turns left again')) };
  if (i === 6) return { col: C.soft, bg: '#f2f2f2', p: cat(tx('done — every popped point was certified interior; the stack holds exactly the hull vertices')) };
  return { col: C.soft, bg: '#f2f2f2', p: cat(tx('the stack holds the vertices of the current hull in counterclockwise order, bottom '), pn('0'), tx(' \u2192 top')) };
}

function drawStrip(g) {
  g.line(20, 344, W - 20, 344).stroke({ color: '#e2e2e2', width: 1 });

  rich(g, 22, 370, tx('stack (bottom \u2192 top)'), { size: 11, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  var st = STACKS[stepIdx];
  var x = 160, y = 370;
  st.s.forEach(function (s, i) {
    var isTop = i === st.s.length - 1;
    g.rect(30, 22).radius(4).move(x, y - 16)
      .fill(isTop ? '#ffe9d3' : '#f3f3f3')
      .stroke({ color: isTop ? C.accent : '#cfcfcf', width: 1 });
    if (s === '…') rich(g, x + 15, y, tx('\u2026'), { size: 13, anchor: 'middle', family: 'sans-serif', halo: false });
    else rich(g, x + 15, y, pn(s), { size: 14, anchor: 'middle', halo: false });
    x += 36;
  });
  if (st.cand) {
    rich(g, x + 10, y, tx('candidate'), { size: 10, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
    g.rect(30, 22).radius(4).move(x + 62, y - 16).fill('#fff')
      .stroke({ color: C.accent, width: 1.2, dasharray: '3,2' });
    rich(g, x + 77, y, pn('i', C.accent), { size: 14, anchor: 'middle', halo: false });
  }

  var v = verdictParts(stepIdx);
  g.rect(546, 30).radius(5).move(22, 388).fill(v.bg).stroke({ color: v.col, width: 1, opacity: 0.5 });
  rich(g, 34, 408, v.p, { size: 12.5, anchor: 'start', fill: v.col, halo: false });

  /* legend */
  var lx = 600, ly = 358;
  g.rect(18, 11).move(lx, ly - 9).fill(C.light).stroke({ color: C.hull, width: 1 });
  rich(g, lx + 26, ly, tx('current hull region'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  g.rect(18, 11).move(lx, ly + 13).fill(C.dark).stroke({ color: C.hull, width: 1 });
  rich(g, lx + 26, ly + 22, tx('region added by the new point'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  g.line(lx, ly + 39, lx + 18, ly + 39).stroke({ color: '#333', width: 1.2, dasharray: '4,3' });
  rich(g, lx + 26, ly + 43, tx('evidence that a point is interior'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  g.circle(7).center(lx + 9, ly + 60).fill(C.accent);
  rich(g, lx + 26, ly + 64, tx('focus of the current turn test'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
}

/* ---------- render ---------- */
function render() {
  gA.clear(); gB.clear(); gStrip.clear();
  var showA = (caseMode === 'a' || caseMode === 'both');
  var showB = (caseMode === 'b' || caseMode === 'both');
  if (showA) { drawA(gA); }
  if (showB) { drawB(gB); }
  if (showA && showB) {
    gA.attr('transform', 'translate(12,6)');
    gB.attr('transform', 'translate(452,6)');
  } else if (showA) {
    gA.attr('transform', 'translate(218,0) scale(1.1)');
  } else {
    gB.attr('transform', 'translate(218,0) scale(1.1)');
  }
  drawStrip(gStrip);
}

/* ---------- controls ---------- */
function toggle_caseToggle(v) {
  caseMode = v;
  if (focusKey && ((caseMode === 'a' && focusKey.charAt(0) === 'B') || (caseMode === 'b' && focusKey.charAt(0) === 'A'))) focusKey = null;
  render();
}
function update_scanStep(i) {
  stepIdx = i;
  render();
}
function trigger_clearFocus() { focusKey = null; hidePopup(); render(); }
function trigger_insight() {
  showPopup('Key insight',
    'A nonleft turn is not just a local wiggle — it is a certificate that the middle point sits inside the triangle formed by its neighbour, the candidate and p_0, so popping it can never remove a true convex-hull vertex.');
}

/* ---------- demo player ---------- */
var DEMO = [
  {
    t: 'The hull so far', c: 'both', s: 0,
    n: 'Panel (a) shows Q_j, the convex hull of the points processed so far, with p_0 at the bottom and p_j at the current top of the stack. Every vertex of Q_j is on the stack in counterclockwise order.'
  },
  {
    t: 'Test the next point: a left turn', c: 'a', s: 1,
    n: 'The candidate p_i is tested against the top two stack entries. The turn at p_j is a left turn, so p_j stays and p_i is accepted — the dark triangle p_0 p_j p_i is the new territory the hull gains.'
  },
  {
    t: 'Push p_i', c: 'a', s: 2,
    n: 'p_i is pushed onto the stack and the hull boundary now bends outward through p_i. Notice the enlarged polygon is still convex.'
  },
  {
    t: 'A nonleft turn instead', c: 'b', s: 3,
    n: 'Panel (b) shows the opposite outcome: the turn at p_t from p_r to p_i is not a left turn. The dashed segments and the marked angle at p_t reveal that p_t lies inside triangle p_i p_r p_0.'
  },
  {
    t: 'Pop the interior point', c: 'b', s: 4,
    n: 'Because p_t is a convex combination of p_i, p_r and p_0, it can never be a hull vertex, so it is popped off the stack — this is why the pop is safe and permanent.'
  },
  {
    t: 'Push the candidate and compare', c: 'both', s: 5,
    n: 'With p_t gone, the candidate is pushed and the chain is convex again. Viewing both panels together contrasts the point that enlarges the hull with the point that is enclosed and discarded.'
  }
];

function applyDemo() {
  var d = DEMO[demoIdx];
