  var n = t.node;
  while (n.firstChild) n.removeChild(n.firstChild);
  n.setAttribute('x', x); n.setAttribute('y', y);
  n.removeAttribute('dy');
  n.setAttribute('text-anchor', opts.anchor || 'start');
