    g.line(P.pt[0], P.pt[1], P.pi[0], P.pi[1]).stroke({ color: dCol, width: 1.2, dasharray: '4,3' }).opacity(dOp);
    g.line(P.pt[0], P.pt[1], P.pr[0], P.pr[1]).stroke({ color: dCol, width: 1.2, dasharray: '4,3' }).opacity(dOp);
    g.polyline(pts(arcPts(P.pt, ang(P.pt, P.pi), ang(P.pt, P.pr), 26)))
      .fill('none').stroke({ color: dCol, width: 1.2, dasharray: '3,2.5' }).opacity(dOp);
  }

  if (stepIdx === 3) {
    g.polyline(pts([P.pr, P.pt, P.pi])).fill('none')
      .stroke({ color: C.accent, width: 3.2, linejoin: 'round', linecap: 'round' }).opacity(0.85);
  }
  if (focusKey === 'B.pr') { g.polyline(pts([P.pi, P.pr, P.p0])).fill('none').stroke({ color: C.accent, width: 3.5, linejoin: 'round' }); ring(g, P.pr); }
  if (focusKey === 'B.pi') { g.polyline(pts([P.pr, P.pi, P.p0])).fill('none').stroke({ color: C.accent, width: 3.5, linejoin: 'round' }); ring(g, P.pi); }
  if (focusKey === 'B.pt' && !pushed) ring(g, P.pt);

  /* dots */
  [P.p0, P.p1, P.e1, P.e2, P.e3, P.e4, P.pj, P.pr, P.pi].forEach(function (p) { dot(g, p, 4); });
  if (stepIdx === 3) { dot(g, P.pt, 5, C.accent); dot(g, P.pr, 5, C.accent); dot(g, P.pi, 5, C.accent); }
  if (!popped) { if (stepIdx !== 3) dot(g, P.pt, 4); }
  else if (!pushed) {
    g.circle(9).center(P.pt[0], P.pt[1]).fill('#fff').stroke({ color: C.bad, width: 1.4 });
    g.line(P.pt[0] - 5, P.pt[1] - 5, P.pt[0] + 5, P.pt[1] + 5).stroke({ color: C.bad, width: 1.6 });
    g.line(P.pt[0] - 5, P.pt[1] + 5, P.pt[0] + 5, P.pt[1] - 5).stroke({ color: C.bad, width: 1.6 });
  }
  if (pushed) dot(g, P.pi, 5, stepIdx === 5 ? C.accent : '#000');

  /* labels */
  rich(g, 52, 90, pn('i'), { size: 16, anchor: 'end' });
  rich(g, 144, 90, pn('r'), { size: 16, anchor: 'start' });
  if (!pushed) rich(g, 104, 148, pn('t'), { size: 16, anchor: 'middle', fill: popped ? C.bad : C.ink, opacity: popped ? 0.6 : 1 });
  rich(g, 162, 22, pn('j'), { size: 16, anchor: 'middle' });
  rich(g, 314, 246, pn('1'), { size: 16, anchor: 'start' });
  rich(g, 86, 278, pn('0'), { size: 16, anchor: 'middle' });
  rich(g, 200, 316, tx('(b)'), { size: 15, anchor: 'middle', family: 'Georgia,serif' });

  /* interaction */
  hit(g, P.pi, 'p_i — the candidate being tested', 'B.pi', 'p_i is the candidate',
    'p_i is the next point in angular order. Together with p_r and p_0 it forms the triangle that traps p_t, which is why p_t can be discarded before p_i is pushed.');
  hit(g, P.pr, 'p_r — next-to-top of the stack', 'B.pr', 'p_r is the witness below p_t',
    'p_r sits immediately below p_t on the stack. It supplies one corner of triangle p_i p_r p_0; after p_t is popped, p_r becomes the new top and the chain p_r → p_i turns left.');
  if (!pushed) hit(g, P.pt, 'p_t — top of stack, makes a nonleft turn', 'B.pt', 'p_t is trapped inside the triangle',
    'The turn (p_r, p_t, p_i) is not a left turn. That certifies p_t lies inside triangle p_i p_r p_0, so p_t is a convex combination of three other points and can never be a hull vertex — popping it is safe and permanent.');
  hit(g, P.p0, 'p_0 — the lowest point, bottom of the stack', null);
}

/* ---------- bottom strip: stack readout, verdict, legend ---------- */
var STACKS = [
  { s: ['0', '1', '2', '…', 'k', 'j'], cand: null },
  { s: ['0', '1', '2', '…', 'k', 'j'], cand: 'i' },
  { s: ['0', '1', '2', '…', 'k', 'j', 'i'], cand: null },
  { s: ['0', '1', '…', 'j', 'r', 't'], cand: 'i' },
  { s: ['0', '1', '…', 'j', 'r'], cand: 'i' },
  { s: ['0', '1', '…', 'j', 'r', 'i'], cand: null },
  { s: ['0', '1', '…', 'j', 'r', 'i'], cand: null }
];

function verdictParts(i) {
  if (i === 1) return { col: C.good, bg: '#e8f6ec', p: cat(tx('turn ('), pn('k'), tx(', '), pn('j'), tx(', '), pn('i'), tx(')  =  LEFT TURN  →  keep '), pn('j'), tx(', push '), pn('i')) };
  if (i === 2) return { col: C.good, bg: '#e8f6ec', p: cat(pn('i'), tx(' pushed — the hull grows by the dark triangle '), pn('0'), tx(' '), pn('j'), tx(' '), pn('i')) };
  if (i === 3) return { col: C.bad, bg: '#fdecea', p: cat(tx('turn ('), pn('r'), tx(', '), pn('t'), tx(', '), pn('i'), tx(')  =  NONLEFT  →  '), pn('t'), tx(' lies inside \u25B3'), pn('i'), tx(' '), pn('r'), tx(' '), pn('0'), tx('  →  pop')) };
  if (i === 4) return { col: C.bad, bg: '#fdecea', p: cat(pn('t'), tx(' popped — an interior point can never be a hull vertex')) };
  if (i === 5) return { col: C.good, bg: '#e8f6ec', p: cat(tx('candidate '), pn('i'), tx(' pushed — the chain '), pn('r'), tx(' \u2192 '), pn('i'), tx(' turns left again')) };
  if (i === 6) return { col: C.soft, bg: '#f2f2f2', p: cat(tx('done — every popped point was certified interior; the stack holds exactly the hull vertices')) };
  return { col: C.soft, bg: '#f2f2f2', p: cat(tx('the stack holds the vertices of the current hull in counterclockwise order, bottom '), pn('0'), tx(' \u2192 top')) };
}

function drawStrip(g) {
  g.line(20, 344, W - 20, 344).stroke({ color: '#e2e2e2', width: 1 });

  rich(g, 22, 370, tx('stack (bottom \u2192 top)'), { size: 11, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  var st = STACKS[stepIdx];
  var x = 160, y = 370;
  st.s.forEach(function (s, i) {
    var isTop = i === st.s.length - 1;
    g.rect(30, 22).radius(4).move(x, y - 16)
      .fill(isTop ? '#ffe9d3' : '#f3f3f3')
      .stroke({ color: isTop ? C.accent : '#cfcfcf', width: 1 });
    if (s === '…') rich(g, x + 15, y, tx('\u2026'), { size: 13, anchor: 'middle', family: 'sans-serif', halo: false });
    else rich(g, x + 15, y, pn(s), { size: 14, anchor: 'middle', halo: false });
    x += 36;
  });
  if (st.cand) {
    rich(g, x + 10, y, tx('candidate'), { size: 10, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
    g.rect(30, 22).radius(4).move(x + 62, y - 16).fill('#fff')
      .stroke({ color: C.accent, width: 1.2, dasharray: '3,2' });
    rich(g, x + 77, y, pn('i', C.accent), { size: 14, anchor: 'middle', halo: false });
  }

  var v = verdictParts(stepIdx);
  g.rect(546, 30).radius(5).move(22, 388).fill(v.bg).stroke({ color: v.col, width: 1, opacity: 0.5 });
  rich(g, 34, 408, v.p, { size: 12.5, anchor: 'start', fill: v.col, halo: false });

  /* legend */
  var lx = 600, ly = 358;
  g.rect(18, 11).move(lx, ly - 9).fill(C.light).stroke({ color: C.hull, width: 1 });
  rich(g, lx + 26, ly, tx('current hull region'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  g.rect(18, 11).move(lx, ly + 13).fill(C.dark).stroke({ color: C.hull, width: 1 });
  rich(g, lx + 26, ly + 22, tx('region added by the new point'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  g.line(lx, ly + 39, lx + 18, ly + 39).stroke({ color: '#333', width: 1.2, dasharray: '4,3' });
  rich(g, lx + 26, ly + 43, tx('evidence that a point is interior'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
  g.circle(7).center(lx + 9, ly + 60).fill(C.accent);
  rich(g, lx + 26, ly + 64, tx('focus of the current turn test'), { size: 10.5, anchor: 'start', family: 'sans-serif', fill: C.soft, halo: false });
}

/* ---------- render ---------- */
function render() {
  gA.clear(); gB.clear(); gStrip.clear();
  var showA = (caseMode === 'a' || caseMode === 'both');
  var showB = (caseMode === 'b' || caseMode === 'both');
  if (showA) { drawA(gA); }
  if (showB) { drawB(gB); }
  if (showA && showB) {
    gA.attr('transform', 'translate(12,6)');
    gB.attr('transform', 'translate(452,6)');
  } else if (showA) {
    gA.attr('transform', 'translate(218,0) scale(1.1)');
  } else {
    gB.attr('transform', 'translate(218,0) scale(1.1)');
  }
  drawStrip(gStrip);
}

/* ---------- controls ---------- */
function toggle_caseToggle(v) {
  caseMode = v;
  if (focusKey && ((caseMode === 'a' && focusKey.charAt(0) === 'B') || (caseMode === 'b' && focusKey.charAt(0) === 'A'))) focusKey = null;
  render();
}
function update_scanStep(i) {
  stepIdx = i;
  render();
}
function trigger_clearFocus() { focusKey = null; hidePopup(); render(); }
function trigger_insight() {
  showPopup('Key insight',
    'A nonleft turn is not just a local wiggle — it is a certificate that the middle point sits inside the triangle formed by its neighbour, the candidate and p_0, so popping it can never remove a true convex-hull vertex.');
}

/* ---------- demo player ---------- */
var DEMO = [
  {
    t: 'The hull so far', c: 'both', s: 0,
    n: 'Panel (a) shows Q_j, the convex hull of the points processed so far, with p_0 at the bottom and p_j at the current top of the stack. Every vertex of Q_j is on the stack in counterclockwise order.'
  },
  {
    t: 'Test the next point: a left turn', c: 'a', s: 1,
    n: 'The candidate p_i is tested against the top two stack entries. The turn at p_j is a left turn, so p_j stays and p_i is accepted — the dark triangle p_0 p_j p_i is the new territory the hull gains.'
  },
  {
    t: 'Push p_i', c: 'a', s: 2,
    n: 'p_i is pushed onto the stack and the hull boundary now bends outward through p_i. Notice the enlarged polygon is still convex.'
  },
  {
    t: 'A nonleft turn instead', c: 'b', s: 3,
    n: 'Panel (b) shows the opposite outcome: the turn at p_t from p_r to p_i is not a left turn. The dashed segments and the marked angle at p_t reveal that p_t lies inside triangle p_i p_r p_0.'
  },
  {
    t: 'Pop the interior point', c: 'b', s: 4,
    n: 'Because p_t is a convex combination of p_i, p_r and p_0, it can never be a hull vertex, so it is popped off the stack — this is why the pop is safe and permanent.'
  },
  {
    t: 'Push the candidate and compare', c: 'both', s: 5,
    n: 'With p_t gone, the candidate is pushed and the chain is convex again. Viewing both panels together contrasts the point that enlarges the hull with the point that is enclosed and discarded.'
  }
];

function applyDemo() {
  var d = DEMO[demoIdx];
  document.getElementById('caseToggleInput').value = d.c;
  document.getElementById('scanStepInput').value = String(d.s);
  focusKey = null;
  toggle_caseToggle(d.c);
  update_scanStep(d.s);
  document.getElementById('demoNarration').textContent = d.t + ' — ' + d.n;
  document.getElementById('stepLabel').textContent = 'step ' + (demoIdx + 1) + ' / ' + DEMO.length;
}
function nextStep() { demoIdx = (demoIdx + 1) % DEMO.length; applyDemo(); }
function prevStep() { demoIdx = (demoIdx - 1 + DEMO.length) % DEMO.length; applyDemo(); }

/* ---------- init ---------- */
render();
applyDemo();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In Graham's scan, the turn direction at the top of the stack decides hull membership: a left turn at p_j means the new point p_i expands the hull, while a nonleft turn means the middle point p_t lies inside the triangle p_i p_r p_0 and can never be a convex-hull vertex.
KEY INSIGHT (what students should walk away understanding): A nonleft turn is not just a local wiggle — it is a certificate that the middle point sits inside the triangle formed by its neighbor, the candidate, and p_0, so popping it can never remove a true hull vertex.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "In Graham's scan, the turn direction at the top of the stack decides hull membership: a left turn at p_j means the new point p_i expands the hull, while a nonleft turn means the middle point p_t lies inside the triangle p_i p_r p_0 and can never be a convex-hull vertex.",
  "figureType": "diagram",
  "elements": [
    "Panel (a) label centered under the left figure",
    "Panel (b) label centered under the right figure",
    "Panel (a): light-gray filled convex polygon Q_j with italic label 'Q_j' in its interior",
    "Panel (a): boundary vertices of Q_j drawn as small filled black dots — p_0 (bottom left), p_j (top), p_k (upper right of p_j), two unlabeled dots along the upper-right chain, p_2 (right), p_1 (lower right)",
    "Panel (a): thick gray polyline forming the hull boundary of Q_j from p_0 up to p_j, across through p_k and the unlabeled dots, down to p_2, back through p_1 to p_0",
    "Panel (a): darker-gray filled triangle p_0–p_j–p_i attached on the left side of Q_j, with p_i lying outside Q_j",
    "Panel (a): vertex labels p_i, p_j, p_k, p_2, p_1, p_0 in italic serif, offset outward from each dot",
    "Panel (a): the shared edge p_0–p_j drawn as the internal boundary between the two shaded regions",
    "Panel (b): thick gray open hull chain from p_0 along the bottom to p_1, up the right side through two unlabeled dots, across the top through an unlabeled dot to p_j, and continuing left toward p_i",
    "Panel (b): small filled black dots at p_0, p_1, p_j, p_i, p_r, p_t and the unlabeled intermediate hull points",
    "Panel (b): thin-outlined light-gray triangle with corners p_i (upper left), p_r (upper right of p_i), p_0 (bottom)",
    "Panel (b): interior point p_t inside the triangle",
    "Panel (b): dashed segments p_t–p_i and p_t–p_r",
    "Panel (b): small arc at p_t marking the angle ∠p_i p_t p_r (obtuse, reflex-side indicator of the nonleft turn)",
    "Panel (b): vertex labels p_i, p_r, p_t, p_j, p_1, p_0",
    "Stack readout strip showing the current Graham-scan stack contents (bottom-to-top) for the stepping interaction",
    "Turn-test annotation box showing the current triple (prev, top, candidate) and the verdict 'left turn → push' or 'nonleft turn → pop'",
    "Legend: light gray = current hull region, dark gray = region added by the new point, dashed = evidence that a point is interior"
  ],
  "interactions": [
    {
      "id": "caseToggle",
      "type": "toggle",
      "teaches": "That the same turn test has two outcomes: a left turn grows the hull (panel a), a nonleft turn proves the middle point is trapped inside a triangle of other points (panel b).",
      "label": "Case",
      "options": [
        "(a) left turn — point joins hull",
        "(b) nonleft turn — point is interior",
        "both panels"
      ],
      "default": "both panels"
    },
    {
      "id": "scanStep",
      "type": "state",
      "teaches": "That Graham's scan processes points in sorted angular order, and at each candidate it repeatedly pops while the top of the stack makes a nonleft turn before pushing the candidate.",
      "label": "Graham-scan stack update",
      "states": [
        "start",
        "test p_j (left turn)",
        "push p_i onto stack",
        "test p_t (nonleft turn)",
        "pop p_t",
        "push p_r",
        "done"
      ],
      "default": "start"
    },
    {
      "id": "pointFocus",
      "type": "click",
      "teaches": "Which specific neighboring points act as the witnesses that place the clicked point on the hull boundary or strictly inside it.",
      "teachesDetail": "Clicking p_i, p_j, p_r or p_t highlights that point and its supporting triangle or hull edge."
    }
  ],
  "demo_steps": [
    {
      "title": "The hull so far",
      "narration": "Panel (a) shows Q_j, the convex hull of the points processed so far, with p_0 at the bottom and p_j at the current top of the stack. Every vertex of Q_j is on the stack in counterclockwise order.",
      "state": {
        "caseToggle": "(a) left turn — point joins hull",
        "scanStep": "start"
      }
    },
    {
      "title": "Test the next point: a left turn",
      "narration": "The candidate p_i is tested against the top two stack entries. The turn at p_j is a left turn, so p_j stays and p_i is accepted — the dark triangle p_0 p_j p_i is the new territory the hull gains.",
      "state": {
        "caseToggle": "(a) left turn — point joins hull",
        "scanStep": "test p_j (left turn)"
      }
    },
    {
      "title": "Push p_i",
      "narration": "p_i is pushed onto the stack and the hull boundary now bends outward through p_i. Notice the enlarged polygon is still convex.",
      "state": {
        "caseToggle": "(a) left turn — point joins hull",
        "scanStep": "push p_i onto stack"
      }
    },
    {
      "title": "A nonleft turn instead",
      "narration": "Panel (b) shows the opposite outcome: the turn at p_t from p_i to p_r is not a left turn. The dashed segments and the marked angle at p_t reveal p_t lies inside triangle p_i p_r p_0.",
      "state": {
        "caseToggle": "(b) nonleft turn — point is interior",
        "scanStep": "test p_t (nonleft turn)"
      }
    },
    {
      "title": "Pop the interior point",
      "narration": "Because p_t is a convex combination of p_i, p_r and p_0, it can never be a hull vertex, so it is popped off the stack — this is why the pop is safe and permanent.",
      "state": {
        "caseToggle": "(b) nonleft turn — point is interior",
        "scanStep": "pop p_t"
      }
    },
    {
      "title": "Push the candidate and compare",
      "narration": "With p_t gone, p_r is pushed and the chain is convex again. Viewing both panels together contrasts the point that enlarges the hull with the point that is enclosed and discarded.",
      "state": {
        "caseToggle": "both panels",
        "scanStep": "push p_r"
      }
    }
  ],
  "keyInsight": "A nonleft turn is not just a local wiggle — it is a certificate that the middle point sits inside the triangle formed by its neighbor, the candidate, and p_0, so popping it can never remove a true hull vertex.",
  "reconstructionNotes": "Two side-by-side panels on white, each about half the width, with italic serif point labels and small filled black dots at every vertex. Panel (a): a light-gray (about 15% gray) convex polygon labeled Q_j occupying the right two-thirds, its thick medium-gray outline running p_0 (bottom left) → p_j (top) → p_k → two unlabeled dots → p_2 (right) → p_1 (lower right) → back to p_0; a darker gray (about 35% gray) triangle p_0–p_j–p_i hangs off the left, p_i well outside the original hull, so the union reads as one larger convex polygon. Panel (b): a thick medium-gray open chain traces the right portion of a hull from p_0 (bottom left) rightward to p_1, up the right side through two unlabeled dots, across the top through a dot to p_j, heading left toward p_i; at the left a narrow light-gray triangle with thin black outline has corners p_i (upper left), p_r (upper right, near the chain), p_0 (bottom), with p_t a dot inside it, thin dashed segments from p_t to p_i and to p_r, and a small dashed arc at p_t marking the angle. Labels (a) and (b) centered below each panel. Highlight color for clicks and the active turn test should be a saturated accent (e.g. orange) applied to the focal point, its two witness segments, and the supporting triangle fill; the stack readout and turn verdict appear as a small text strip below the panels.",
  "figureType_note": "diagram → rendered with SVG.js so arbitrary polygons, dashed witnesses, and highlight states can be redrawn per step."
}

